const bytesToB64=(a:Uint8Array)=>btoa(String.fromCharCode(...a));
const b64ToBytes=(s:string)=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
async function hashPassword(password:string,salt:Uint8Array){
  const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);
  return bytesToB64(new Uint8Array(await crypto.subtle.deriveBits({name:'PBKDF2',salt:salt as BufferSource,iterations:10000,hash:'SHA-256'},material,256)));
}
async function sign(payload:string,key:string){
  const k=await crypto.subtle.importKey('raw',new TextEncoder().encode(key),{name:'HMAC',hash:'SHA-256'},false,['sign']);
  return bytesToB64(new Uint8Array(await crypto.subtle.sign('HMAC',k,new TextEncoder().encode(payload)))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
}
async function sessionKey(db:D1Database){ const a=await db.prepare('SELECT password_hash FROM admins WHERE id=1').first<{password_hash:string}>(); return a?.password_hash||'no-admin'; }
async function requireAuth(c:any,next:any){
  if(c.req.path==='/login'||c.req.path==='/setup'||c.req.path.startsWith('/api/auth/')) return next();
  const token=getCookie(c,'oc_session'); if(!token){ if(c.req.path.startsWith('/api/')) return c.json({error:'No autorizado'},401); return c.redirect('/login'); }
  const [payload,sig]=token.split('.'); if(!payload||!sig||await sign(payload,await sessionKey(c.env.DB))!==sig) { deleteCookie(c,'oc_session'); return c.redirect('/login'); }
  const data=JSON.parse(atob(payload)); if(data.exp<Date.now()) { deleteCookie(c,'oc_session'); return c.redirect('/login'); }
  return next();
}
app.use('*',requireAuth);

