const shell=(content:any)=>html`<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#264f40"><title>Olas de Chile · Gestión</title><style>${styles}</style></head><body>${content}</body></html>`;

app.get('/setup', async c=>{
  const exists=await c.env.DB.prepare('SELECT id FROM admins WHERE id=1').first(); if(exists) return c.redirect('/login');
  return c.html(shell(html`<main class="auth"><section class="auth-card"><div class="brand"><img class="logo" src="${LOGO}" alt="Olas de Chile Ecocamp"><div><h1>OLAS DE CHILE</h1><small>ECOCAMP · PUNTA DE LOBOS</small></div></div><h2>Crear administrador</h2><p class="muted">Este paso solo aparece una vez. Crea el único acceso para gestionar el ecocamp.</p><form id="setup"><label>Usuario</label><input name="username" minlength="3" required autocomplete="username"><label>Contraseña</label><input name="password" type="password" minlength="10" required autocomplete="new-password"><label>Confirmar contraseña</label><input name="confirm" type="password" minlength="10" required autocomplete="new-password"><p class="error" id="error"></p><button class="btn wide">Crear acceso</button></form></section></main><script>document.querySelector('#setup').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),data=Object.fromEntries(f);if(data.password!==data.confirm){error.textContent='Las contraseñas no coinciden';return}const r=await fetch('/api/auth/setup',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(data)});const j=await r.json();if(!r.ok){error.textContent=j.error;return}location.href='/'}</script>`));
});
app.get('/login', async c=>{
  const exists=await c.env.DB.prepare('SELECT id FROM admins WHERE id=1').first(); if(!exists) return c.redirect('/setup');
  return c.html(shell(html`<main class="auth"><section class="auth-card"><div class="brand"><img class="logo" src="${LOGO}" alt="Olas de Chile Ecocamp"><div><h1>OLAS DE CHILE</h1><small>ECOCAMP · PUNTA DE LOBOS</small></div></div><h2>Bienvenido</h2><p class="muted">Ingresa para gestionar reservas, llegadas y ocupación.</p><form id="login"><label>Usuario</label><input name="username" required autocomplete="username"><label>Contraseña</label><input name="password" type="password" required autocomplete="current-password"><p class="error" id="error"></p><button class="btn wide">Ingresar</button></form></section></main><script>document.querySelector('#login').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));const r=await fetch('/api/auth/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(data)});const j=await r.json();if(!r.ok){error.textContent=j.error;return}location.href='/'}</script>`));
});
app.post('/api/auth/setup',async c=>{
  const body=await c.req.json<{username:string,password:string}>(); if(!body.username||body.username.length<3||!body.password||body.password.length<10) return c.json({error:'Usa un usuario y una contraseña de al menos 10 caracteres'},400);
  const salt=crypto.getRandomValues(new Uint8Array(16)),password_hash=await hashPassword(body.password,salt);
  try{await c.env.DB.prepare('INSERT INTO admins(id,username,password_hash,salt) VALUES(1,?,?,?)').bind(body.username,password_hash,bytesToB64(salt)).run();}catch{return c.json({error:'El administrador ya fue creado'},409)}
  const payload=btoa(JSON.stringify({u:body.username,exp:Date.now()+86400000})); setCookie(c,'oc_session',`${payload}.${await sign(payload,password_hash)}`,{httpOnly:true,secure:true,sameSite:'Strict',maxAge:86400,path:'/'}); return c.json({ok:true});
});
app.post('/api/auth/login',async c=>{
  const b=await c.req.json<{username:string,password:string}>(),a=await c.env.DB.prepare('SELECT username,password_hash,salt FROM admins WHERE id=1').first<any>();
  if(!a||a.username!==b.username||await hashPassword(b.password,b64ToBytes(a.salt))!==a.password_hash) return c.json({error:'Usuario o contraseña incorrectos'},401);
  const payload=btoa(JSON.stringify({u:a.username,exp:Date.now()+86400000})); setCookie(c,'oc_session',`${payload}.${await sign(payload,a.password_hash)}`,{httpOnly:true,secure:true,sameSite:'Strict',maxAge:86400,path:'/'}); return c.json({ok:true});
});
app.post('/api/auth/logout',c=>{deleteCookie(c,'oc_session',{path:'/'});return c.json({ok:true})});
app.get('/api/reservations',async c=>c.json({reservations:(await c.env.DB.prepare('SELECT * FROM reservations ORDER BY check_in,site_code').all<Reservation>()).results,sites:SITES}));
app.post('/api/reservations',async c=>{
  const b=await c.req.json<any>(); if(!SITES.some(s=>s.code===b.site_code)||!b.guest_name||!b.check_in||!b.check_out||b.check_out<=b.check_in) return c.json({error:'Revisa sitio, huésped y fechas'},400);
  const overlap=await c.env.DB.prepare('SELECT id FROM reservations WHERE site_code=? AND check_in < ? AND check_out > ?').bind(b.site_code,b.check_out,b.check_in).first(); if(overlap)return c.json({error:'Ese sitio ya está reservado en esas fechas'},409);
  const code=`R-${String(Date.now()).slice(-6)}`; const r=await c.env.DB.prepare('INSERT INTO reservations(code,site_code,guest_name,phone,guests,check_in,check_out,total_clp,paid_clp,source,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?)').bind(code,b.site_code,b.guest_name,b.phone||'',Number(b.guests)||1,b.check_in,b.check_out,Number(b.total_clp)||0,Number(b.paid_clp)||0,b.source||'Directo',b.notes||'').run(); return c.json({ok:true,id:r.meta.last_row_id,code});
});
app.put('/api/reservations/:id',async c=>{
  const id=Number(c.req.param('id')),b=await c.req.json<any>(); if(!id||!SITES.some(s=>s.code===b.site_code)||!b.guest_name||!b.check_in||!b.check_out||b.check_out<=b.check_in)return c.json({error:'Revisa los datos'},400);
  const overlap=await c.env.DB.prepare('SELECT id FROM reservations WHERE site_code=? AND check_in < ? AND check_out > ? AND id<>?').bind(b.site_code,b.check_out,b.check_in,id).first(); if(overlap)return c.json({error:'Ese sitio ya está reservado en esas fechas'},409);
  await c.env.DB.prepare('UPDATE reservations SET site_code=?,guest_name=?,phone=?,guests=?,check_in=?,check_out=?,total_clp=?,paid_clp=?,source=?,notes=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').bind(b.site_code,b.guest_name,b.phone||'',Number(b.guests)||1,b.check_in,b.check_out,Number(b.total_clp)||0,Number(b.paid_clp)||0,b.source||'Directo',b.notes||'',id).run(); return c.json({ok:true});
});
app.delete('/api/reservations/:id',async c=>{await c.env.DB.prepare('DELETE FROM reservations WHERE id=?').bind(Number(c.req.param('id'))).run();return c.json({ok:true})});

app.post('/api/demo-seed',async c=>{
  await c.env.DB.prepare("DELETE FROM reservations WHERE code LIKE 'DEMO-%'").run();
  const stmts=DEMO.map(r=>c.env.DB.prepare('INSERT INTO reservations(code,site_code,guest_name,phone,guests,check_in,check_out,total_clp,paid_clp,source,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?)').bind(...r));
  for(let i=0;i<stmts.length;i+=100)await c.env.DB.batch(stmts.slice(i,i+100));
  return c.json({ok:true,count:DEMO.length});
});

app.get('/',c=>c.html(shell(html`<div class="shell"><header class="topbar"><div class="brand"><img class="logo" src="${LOGO}" alt="Olas de Chile Ecocamp"><div><h1>OLAS DE CHILE</h1><small>ECOCAMP · PUNTA DE LOBOS</small></div></div><nav class="nav"><button class="active" data-view="mapa">Mapa</button><button data-view="plan">Planificación</button><button data-view="mov">Llegadas y salidas</button><button data-view="stats">Estadísticas</button></nav><div class="spacer"></div><button class="avatar" id="logout">OC</button></header><main class="content"><section id="mapa"></section><section id="plan" class="hidden"></section><section id="mov" class="hidden"></section><section id="stats" class="hidden"></section></main><footer class="footer">Olas de Chile Ecocamp · Alto Punta de Lobos, Pichilemu</footer></div><div id="modal" class="modal hidden"></div><script>const SITES=${raw(JSON.stringify(SITES))};${raw('let reservations=[],selectedDate=new Date().toISOString().slice(0,10),selected=null;\nconst money=n=>new Intl.NumberFormat(\'es-CL\',{style:\'currency\',currency:\'CLP\',maximumFractionDigits:0}).format(n||0);const fmt=d=>new Intl.DateTimeFormat(\'es-CL\',{weekday:\'short\',day:\'numeric\',month:\'long\'}).format(new Date(d+\'T12:00:00\'));const esc=s=>String(s??\'\').replace(/[&<>"\']/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c]));\nconst state=(site,date=selectedDate)=>{const r=reservations.find(x=>x.site_code===site&&x.check_in<=date&&x.check_out>=date);if(!r)return{status:\'free\'};if(r.check_in===date)return{status:\'arrival\',r};if(r.check_out===date)return{status:\'departure\',r};return{status:\'occupied\',r}};\nasync function load(){const r=await fetch(\'/api/reservations\');if(r.status===401){location=\'/login\';return}reservations=(await r.json()).reservations;renderAll()}\nfunction head(title,sub){const occ=SITES.filter(s=>state(s.code).status!==\'free\').length;return `<div class="page-head"><div><div class="eyebrow">Vista general</div><h2>${title}</h2><div class="muted">${sub}</div></div><div class="occupancy"><strong>${Math.round(occ/SITES.length*100)}%</strong><br>ocupación</div></div>`}\nfunction dates(){return `<div class="date-strip">${[...Array(7)].map((_,i)=>{const d=new Date(selectedDate+\'T12:00:00\');d.setDate(d.getDate()+i-1);const iso=d.toISOString().slice(0,10);return `<button class="${iso===selectedDate?\'active\':\'\'}" data-date="${iso}">${fmt(iso)}</button>`}).join(\'\')}</div>`}\nfunction siteButton(s){const st=state(s.code);return `<button class="site ${st.status} ${selected===s.code?\'selected\':\'\'}" data-site="${s.code}"><b>${s.code}</b><small>${s.capacity} pers.</small></button>`}\nfunction detail(){if(!selected)return `<div class="detail"><h3>Selecciona un sitio</h3><p class="muted">Haz clic en un sitio para ver su estado o crear una reserva.</p></div>`;const s=SITES.find(x=>x.code===selected),st=state(selected),r=st.r;if(!r)return `<div class="detail"><span class="pill">Libre</span><h3>${s.type} · ${s.code}</h3><p class="muted">Capacidad para ${s.capacity} personas. Disponible el ${fmt(selectedDate)}.</p><div class="detail-actions"><button class="btn" onclick="openForm(null,\'${s.code}\')">Nueva reserva</button></div></div>`;return `<div class="detail"><span class="pill">${st.status===\'arrival\'?\'Llega hoy\':st.status===\'departure\'?\'Sale hoy\':\'Ocupado\'}</span><h3>${s.type} · ${s.code}</h3><label>Huésped</label><b>${esc(r.guest_name)}</b><div class="muted">${r.guests} personas · ${esc(r.source)}</div><div class="facts"><div><small>Entrada</small><b>${fmt(r.check_in)}</b></div><div><small>Salida</small><b>${fmt(r.check_out)}</b></div><div><small>Total</small><b>${money(r.total_clp)}</b></div><div><small>Saldo</small><b>${money(r.total_clp-r.paid_clp)}</b></div></div><div class="detail-actions"><button class="btn secondary" onclick="openForm(${r.id})">Editar</button><button class="btn danger" onclick="removeRes(${r.id})">Eliminar</button></div></div>`}\nfunction renderMap(){mapa.innerHTML=head(\'Estado del ecocamp\',`${fmt(selectedDate)} · ${SITES.filter(s=>state(s.code).status!==\'free\').length} de 18 sitios ocupados`)+dates()+`<div class="legend"><span><i class="dot" style="background:#fff;border:1px solid #cad3cd"></i>Libre</span><span><i class="dot" style="background:#264f40"></i>Ocupado</span><span><i class="dot" style="background:#df9a43"></i>Llegada</span><span><i class="dot" style="background:#5790a0"></i>Salida</span></div><div class="map-grid"><div class="map"><div class="ocean"><span>Océano Pacífico</span><span>≈\u3000≈\u3000≈</span></div><div class="zone"><div class="zone-title">MIRADOR</div><div class="sites">${SITES.filter(s=>s.type===\'Mirador\').map(siteButton).join(\'\')}</div></div><div class="path">SENDERO HACIA LA PLAYA</div><div class="zone"><div class="zone-title">BOSQUE NATIVO</div><div class="sites">${SITES.filter(s=>s.type===\'Bosque\').map(siteButton).join(\'\')}</div></div><div class="zone"><div class="zone-title">GLAMPING</div><div class="sites">${SITES.filter(s=>s.type===\'Glamping\').map(siteButton).join(\'\')}</div></div></div>${detail()}</div>`;document.querySelectorAll(\'[data-date]\').forEach(b=>b.onclick=()=>{selectedDate=b.dataset.date;renderAll()});document.querySelectorAll(\'[data-site]\').forEach(b=>b.onclick=()=>{selected=b.dataset.site;renderMap()})}\nfunction renderPlan(){plan.innerHTML=head(\'Planificación\',\'Todas las reservas del ecocamp\')+`<div class="toolbar"><input id="search" placeholder="Buscar huésped, reserva o sitio"><button class="btn" onclick="openForm()">Nueva reserva</button></div><div class="table-wrap"><table><thead><tr><th>Reserva</th><th>Sitio</th><th>Huésped</th><th>Fechas</th><th>Total</th><th>Saldo</th><th></th></tr></thead><tbody id="rows">${planRows(reservations)}</tbody></table></div>`;search.oninput=()=>rows.innerHTML=planRows(reservations.filter(r=>(r.guest_name+r.code+r.site_code).toLowerCase().includes(search.value.toLowerCase())))}\nfunction planRows(list){list=[...list].sort((a,b)=>{const ap=a.check_in<todayIso,bp=b.check_in<todayIso;if(ap!==bp)return ap?1:-1;return ap?b.check_in.localeCompare(a.check_in):a.check_in.localeCompare(b.check_in)});return list.length?list.map(r=>`<tr><td><b>${r.code}</b></td><td>${r.site_code}</td><td><b>${esc(r.guest_name)}</b><div class="muted">${r.guests} pers.</div></td><td>${fmt(r.check_in)} → ${fmt(r.check_out)}</td><td>${money(r.total_clp)}</td><td>${money(r.total_clp-r.paid_clp)}</td><td><button class="btn secondary" onclick="openForm(${r.id})">Editar</button></td></tr>`).join(\'\'):`<tr><td colspan="7" class="empty">Aún no hay reservas</td></tr>`}\nfunction renderMov(){const today=selectedDate,arr=reservations.filter(r=>r.check_in===today),dep=reservations.filter(r=>r.check_out===today);mov.innerHTML=head(\'Llegadas y salidas\',fmt(today))+dates()+`<div class="map-grid"><div class="panel"><div class="eyebrow">Llegadas · ${arr.length}</div>${moveList(arr,\'Llegada\')}</div><div class="panel"><div class="eyebrow">Salidas · ${dep.length}</div>${moveList(dep,\'Salida\')}</div></div>`;mov.querySelectorAll(\'[data-date]\').forEach(b=>b.onclick=()=>{selectedDate=b.dataset.date;renderAll()})}\nfunction moveList(list,label){return list.length?list.map(r=>`<div style="padding:16px 0;border-bottom:1px solid var(--line)"><b>${r.site_code} · ${esc(r.guest_name)}</b><div class="muted">${r.guests} personas · ${r.phone?esc(r.phone):\'sin teléfono\'} · ${label}</div></div>`).join(\'\'):`<div class="empty">Sin movimientos</div>`}\nlet statPeriod=\'mes\';\nconst DAY=86400000,todayIso=new Date().toISOString().slice(0,10),pd=s=>new Date(s+\'T12:00:00\'),piso=x=>x.toISOString().slice(0,10);\nfunction seasonRange(){const t=pd(todayIso),m=t.getMonth(),y=t.getFullYear();const sy=m>=11?y:m<=2?y-1:y;return{from:sy+\'-12-01\',to:(sy+1)+\'-03-31\',label:\'Temporada \'+sy+\'-\'+String(sy+1).slice(2)}}\nfunction periodRange(id){const t=todayIso;if(id===\'hoy\')return[t,t];if(id===\'semana\'){const wd=(pd(t).getDay()+6)%7,f=new Date(pd(t).getTime()-wd*DAY);return[piso(f),piso(new Date(f.getTime()+6*DAY))]}if(id===\'mes\')return[piso(new Date(pd(t).getTime()-29*DAY)),t];if(id===\'semestre\'){const f=pd(t);f.setMonth(f.getMonth()-6);return[piso(f),t]}if(id===\'ano\'){const y=pd(t).getFullYear();return[y+\'-01-01\',y+\'-12-31\']}const s=seasonRange();return[s.from,s.to]}\nfunction occBetween(a,b){let o=0;const A=pd(a).getTime(),B=pd(b).getTime()+DAY;reservations.forEach(r=>{o+=Math.max(0,Math.round((Math.min(pd(r.check_out).getTime(),B)-Math.max(pd(r.check_in).getTime(),A))/DAY))});return o}\nfunction buckets(from,to){const daysIn=Math.round((pd(to)-pd(from))/DAY)+1,out=[];const push=(a,b,label)=>{const o=occBetween(a,b),cap=SITES.length*(Math.round((pd(b)-pd(a))/DAY)+1);out.push({label,pct:Math.round(o/cap*100)})};if(daysIn<=10){for(let i=0;i<daysIn;i++){const d=piso(new Date(pd(from).getTime()+i*DAY));push(d,d,new Intl.DateTimeFormat(\'es-CL\',{weekday:\'short\'}).format(pd(d)))}}else if(daysIn<=70){let s=pd(from);const wd=(s.getDay()+6)%7;s=new Date(s.getTime()-wd*DAY);while(piso(s)<=to){const e=new Date(s.getTime()+6*DAY);push(piso(s),piso(e),new Intl.DateTimeFormat(\'es-CL\',{day:\'numeric\',month:\'short\'}).format(s));s=new Date(e.getTime()+DAY)}}else{let y=pd(from).getFullYear(),m=pd(from).getMonth();while(new Date(y,m,1)<=pd(to)){push(piso(new Date(y,m,1)),piso(new Date(y,m+1,0)),new Intl.DateTimeFormat(\'es-CL\',{month:\'short\'}).format(new Date(y,m,12)));m++;if(m>11){m=0;y++}}}return out}\nfunction chart(bk){const W=640,H=230,P={l:44,r:16,t:28,b:30};const xs=i=>P.l+(W-P.l-P.r)*(bk.length===1?0.5:i/(bk.length-1)),ys=v=>P.t+(H-P.t-P.b)*(1-v/100);let line=\'\',area=\'\',pts=\'\',labels=\'\',xlab=\'\';bk.forEach((b,i)=>{const x=xs(i),y=ys(b.pct);line+=(i?\'L\':\'M\')+x+\',\'+y;area+=(i?\'L\':\'M\')+x+\',\'+y;pts+=\'<circle cx="\'+x+\'" cy="\'+y+\'" r="5" fill="#fff" stroke="#264f40" stroke-width="2.5"/>\';labels+=\'<text x="\'+x+\'" y="\'+(y-12)+\'" text-anchor="middle" style="font:700 12px system-ui;fill:#264f40">\'+b.pct+\'%</text>\';if(bk.length<=12||i%Math.ceil(bk.length/12)===0)xlab+=\'<text x="\'+x+\'" y="\'+(H-8)+\'" text-anchor="middle" style="font:11px system-ui;fill:#9aa39e">\'+b.label+\'</text>\'});area+=\'L\'+xs(bk.length-1)+\',\'+ys(0)+\'L\'+xs(0)+\',\'+ys(0)+\'Z\';let grid=\'\';[0,25,50,75,100].forEach(v=>{grid+=\'<line x1="\'+P.l+\'" x2="\'+(W-P.r)+\'" y1="\'+ys(v)+\'" y2="\'+ys(v)+\'" stroke="#eef1ee"/><text x="\'+(P.l-8)+\'" y="\'+(ys(v)+4)+\'" text-anchor="end" style="font:10px system-ui;fill:#9aa39e">\'+v+\'%</text>\'});const max=Math.max(...bk.map(b=>b.pct));return{max,svg:\'<svg viewBox="0 0 \'+W+\' \'+H+\'" style="width:100%">\'+grid+\'<path d="\'+area+\'" fill="#264f4012"/><path d="\'+line+\'" fill="none" stroke="#264f40" stroke-width="2.5"/>\'+pts+labels+xlab+\'</svg>\'}}\nfunction topWeeks(from,to){const weeks=[];let s=pd(from);const wd=(s.getDay()+6)%7;s=new Date(s.getTime()-wd*DAY);while(piso(s)<=to){const e=new Date(s.getTime()+6*DAY),o=occBetween(piso(s),piso(e));weeks.push({label:new Intl.DateTimeFormat(\'es-CL\',{day:\'numeric\',month:\'short\'}).format(s)+\' – \'+new Intl.DateTimeFormat(\'es-CL\',{day:\'numeric\',month:\'short\'}).format(e),pct:Math.round(o/(SITES.length*7)*100)});s=new Date(e.getTime()+DAY)}return weeks.sort((a,b)=>b.pct-a.pct).slice(0,4)}\nfunction renderStats(){const periods=[[\'hoy\',\'Hoy\'],[\'semana\',\'Esta semana\'],[\'mes\',\'Últimos 30 días\'],[\'semestre\',\'Últimos 6 meses\'],[\'ano\',\'Este año\'],[\'temporada\',seasonRange().label]];const[from,to]=periodRange(statPeriod);const daysIn=Math.round((pd(to)-pd(from))/DAY)+1;let occ=0,rev=0,count=0,stay=0;const byType={};SITES.forEach(s=>byType[s.type]={rev:0,occ:0,sites:0});SITES.forEach(s=>byType[s.type].sites++);reservations.forEach(r=>{const n=Math.round((pd(r.check_out)-pd(r.check_in))/DAY),ov=Math.max(0,Math.round((Math.min(pd(r.check_out).getTime(),pd(to).getTime()+DAY)-Math.max(pd(r.check_in).getTime(),pd(from).getTime()))/DAY)),type=SITES.find(s=>s.code===r.site_code).type;if(ov>0){count++;occ+=ov;stay+=n;const pr=r.total_clp*ov/n;rev+=pr;byType[type].rev+=pr;byType[type].occ+=ov}});const occPct=Math.round(occ/(SITES.length*daysIn)*100),adr=occ?Math.round(rev/occ):0,ch=chart(buckets(from,to)),top=topWeeks(from,to),dist=[[\'Mirador\',7,\'#264f40\'],[\'Bosque\',8,\'#df9a43\'],[\'Glamping\',3,\'#5790a0\']];const bestType=[\'Mirador\',\'Bosque\',\'Glamping\'].map(t=>({t,adr:byType[t].occ?byType[t].rev/byType[t].occ:0})).sort((a,b)=>b.adr-a.adr)[0];const insight1=top.length&&top[0].pct>0?\'La semana del \'+top[0].label+\' llega al \'+top[0].pct+\'%.\':\'Sin reservas en este período.\';const insight2=bestType.adr>0?bestType.t+\' muestra el ingreso más alto por noche: \'+money(Math.round(bestType.adr))+\'.\':\'Carga reservas para ver tendencias.\';stats.innerHTML=head(\'Estadísticas\',fmt(from)+\' → \'+fmt(to))+`<div class="period-strip">${periods.map(p=>`<button class="${p[0]===statPeriod?\'active\':\'\'}" data-period="${p[0]}">${p[1]}</button>`).join(\'\')}</div><div class="stats"><div class="stat"><strong>${occPct}%</strong><span>Ocupación promedio</span><div class="muted" style="font-size:11px;margin-top:5px">${occ} noches vendidas</div></div><div class="stat"><strong>${count?(stay/count).toFixed(1):\'0\'}</strong><span>Estadía media (noches)</span><div class="muted" style="font-size:11px;margin-top:5px">${count} reservas</div></div><div class="stat"><strong>${occ}</strong><span>Noches reservadas</span><div class="muted" style="font-size:11px;margin-top:5px">de ${SITES.length*daysIn} disponibles</div></div><div class="stat"><strong>${money(rev)}</strong><span>Ingresos</span><div class="muted" style="font-size:11px;margin-top:5px">${money(adr)} por noche</div></div></div><div class="map-grid"><div class="panel"><div style="display:flex;justify-content:space-between;align-items:start"><div><div class="eyebrow">Ocupación en el tiempo</div><h3 style="font:400 24px Georgia,serif;margin:5px 0 14px">${fmt(from)} → ${fmt(to)}</h3></div><span class="pill">Máx ${ch.max}%</span></div>${ch.svg}</div><div class="panel"><div class="eyebrow">Distribución del parque</div><h3 style="font:400 24px Georgia,serif;margin:5px 0 6px">18 sitios</h3><div style="display:flex;height:14px;border-radius:8px;overflow:hidden;margin:18px 0">${dist.map(x=>`<div style="width:${x[1]/18*100}%;background:${x[2]}"></div>`).join(\'\')}</div>${dist.map(x=>`<div style="display:flex;align-items:center;gap:10px;padding:9px 0;border-bottom:1px solid var(--line)"><i class="dot" style="background:${x[2]}"></i><b>${x[0]}</b><span style="margin-left:auto" class="muted">${x[1]} sitios</span><b>${Math.round(x[1]/18*100)}%</b></div>`).join(\'\')}</div></div><div class="map-grid" style="margin-top:20px"><div class="panel"><div class="eyebrow">Períodos fuertes</div><h3 style="font:400 24px Georgia,serif;margin:5px 0 14px">Semanas con más demanda</h3>${top.length?top.map((w,i)=>`<div style="display:grid;grid-template-columns:34px 150px 1fr 52px;gap:12px;align-items:center;padding:11px 0;border-bottom:1px solid var(--line)"><span class="pill">${i+1}</span><b>${w.label}</b><div style="height:10px;background:var(--sand);border-radius:8px"><div style="height:100%;width:${w.pct}%;background:var(--forest);border-radius:8px"></div></div><b style="text-align:right">${w.pct}%</b></div>`).join(\'\'):\'<div class="empty">Sin datos en este período</div>\'}</div><div class="panel"><div class="eyebrow">Para tener en cuenta</div><h3 style="font:400 24px Georgia,serif;margin:5px 0 14px">${insight1}</h3><p class="muted">${insight2}</p></div></div>`;stats.querySelectorAll(\'[data-period]\').forEach(b=>b.onclick=()=>{statPeriod=b.dataset.period;renderStats()})}\nfunction renderAll(){renderMap();renderPlan();renderMov();renderStats()}\nfunction openForm(id,site){const r=reservations.find(x=>x.id===id)||{site_code:site||\'M01\',guest_name:\'\',phone:\'\',guests:2,check_in:selectedDate,check_out:new Date(new Date(selectedDate+\'T12:00:00\').getTime()+86400000).toISOString().slice(0,10),total_clp:0,paid_clp:0,source:\'Directo\',notes:\'\'};modal.classList.remove(\'hidden\');modal.innerHTML=`<form class="modal-card" id="resform"><div class="modal-head"><h3>${id?\'Editar\':\'Nueva\'} reserva</h3><button type="button" class="close" onclick="modal.classList.add(\'hidden\')">×</button></div><div class="form-grid"><div><label>Sitio</label><select name="site_code">${SITES.map(s=>`<option ${s.code===r.site_code?\'selected\':\'\'}>${s.code} · ${s.type}</option>`).join(\'\')}</select></div><div><label>Huésped</label><input name="guest_name" value="${esc(r.guest_name)}" required></div><div><label>Teléfono</label><input name="phone" value="${esc(r.phone)}"></div><div><label>Personas</label><input name="guests" type="number" min="1" max="8" value="${r.guests}"></div><div><label>Entrada</label><input name="check_in" type="date" value="${r.check_in}" required></div><div><label>Salida</label><input name="check_out" type="date" value="${r.check_out}" required></div><div><label>Total CLP</label><input name="total_clp" type="number" min="0" step="1000" value="${r.total_clp}"></div><div><label>Pagado CLP</label><input name="paid_clp" type="number" min="0" step="1000" value="${r.paid_clp}"></div><div><label>Origen</label><select name="source">${[\'Directo\',\'Web\',\'Teléfono\',\'Google Calendar\'].map(x=>`<option ${x===r.source?\'selected\':\'\'}>${x}</option>`).join(\'\')}</select></div><div class="full"><label>Notas</label><textarea name="notes" rows="3">${esc(r.notes)}</textarea></div></div><p class="error" id="formerror"></p><button class="btn wide">Guardar reserva</button></form>`;resform.onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));const resp=await fetch(\'/api/reservations\'+(id?\'/\'+id:\'\'),{method:id?\'PUT\':\'POST\',headers:{\'content-type\':\'application/json\'},body:JSON.stringify(data)}),j=await resp.json();if(!resp.ok){formerror.textContent=j.error;return}modal.classList.add(\'hidden\');selected=data.site_code;selectedDate=data.check_in;await load()}}\nasync function removeRes(id){if(!confirm(\'¿Eliminar esta reserva?\'))return;await fetch(\'/api/reservations/\'+id,{method:\'DELETE\'});selected=null;await load()}\ndocument.querySelectorAll(\'[data-view]\').forEach(b=>b.onclick=()=>{document.querySelectorAll(\'[data-view]\').forEach(x=>x.classList.toggle(\'active\',x===b));[\'mapa\',\'plan\',\'mov\',\'stats\'].forEach(x=>document.getElementById(x).classList.toggle(\'hidden\',x!==b.dataset.view))});logout.onclick=async()=>{await fetch(\'/api/auth/logout\',{method:\'POST\'});location=\'/login\'};load();')}</script>`)));
export default app;

